function kururun(n : number, m : number, c1 : string, c2 : string)  : string {
    let s : string = ""
    for (let i : number = 0; i < m * n; i++) {
        let x : number = i % m
        if (x < m/2) {
            s = s + c1
        } else {
            s = s + c2
        }
    }

    return s
}

